package au.monster.tracker;

import android.app.*;
import android.os.Bundle;
import android.content.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;

/** Local catalogue, barcode assignment, stock counts and shopping list. */
public final class CatalogActivity extends Activity {
    private Store store;private CatalogStore catalog;private CatalogStore.View state;private LinearLayout body,items;private TextView status;private boolean busy,dead;private String pendingBarcode;private final ExecutorService io=Executors.newSingleThreadExecutor();
    private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle b){super.onCreate(b);store=new Store(this);catalog=new CatalogStore(store);pendingBarcode=getIntent().getStringExtra("barcode");showList();}
    @Override protected void onDestroy(){dead=true;io.execute(store::close);io.shutdown();super.onDestroy();}
    private TextView text(String value,int size){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(0xfff0f5eb);v.setPadding(12,12,12,12);return v;}
    private Button button(String value,Runnable run){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setMinHeight(dp(64));b.setOnClickListener(v->{if(!busy)run.run();});return b;}
    private EditText field(LinearLayout box,String label,String value,int type){box.addView(text(label,15));EditText e=new EditText(this);e.setText(value);e.setTextColor(0xfff0f5eb);e.setInputType(type);e.setMinHeight(dp(56));box.addView(e);return e;}
    private void shell(String title){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff101410);root.setOnApplyWindowInsetsListener((v,insets)->{root.setPadding(16,insets.getSystemWindowInsetTop()+8,16,insets.getSystemWindowInsetBottom()+8);return insets;});setContentView(root);root.requestApplyInsets();root.addView(text(title,24));status=text("Offline · no stock is added by a scan",14);root.addView(status);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
    private <T> void job(Callable<T> work,java.util.function.Consumer<T> done){if(busy)return;busy=true;status.setText("Working locally…");io.execute(()->{try{T value=work.call();runOnUiThread(()->{if(dead)return;busy=false;done.accept(value);});}catch(Throwable e){runOnUiThread(()->{if(dead)return;busy=false;status.setText("No changes saved.");error(e);});}});}
    private void error(Throwable e){new AlertDialog.Builder(this).setTitle("Could not complete").setMessage(e.getMessage()==null?"No records were changed.":e.getMessage()).setPositiveButton("OK",null).show();}
    private void showList(){shell("Flavours & low stock");body.addView(button("Add flavour",()->edit(null)));body.addView(button("Deleted flavours",this::deletedFlavours));body.addView(button("Scan retail barcode",()->startActivityForResult(new Intent(this,CameraActivity.class).putExtra("mode","barcode"),71)));body.addView(button("Enter / assign barcode manually",()->{EditText code=new EditText(this);new AlertDialog.Builder(this).setTitle("Barcode (keep leading zeros)").setView(code).setNegativeButton("Cancel",null).setPositiveButton("Look up / assign",(d,w)->selectCode(code.getText().toString())).show();}));body.addView(button("Shopping list",this::shopping));body.addView(button("Back",this::finish));EditText search=field(body,"Search flavour name","",android.text.InputType.TYPE_CLASS_TEXT);items=new LinearLayout(this);items.setOrientation(1);body.addView(items);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int n){}public void onTextChanged(CharSequence s,int start,int before,int count){draw(s.toString());}public void afterTextChanged(Editable e){}});job(catalog::view,result->{state=result;draw("");status.setText("Historic quantities remain unassigned until you explicitly identify their flavour.");if(pendingBarcode!=null){String code=pendingBarcode;pendingBarcode=null;selectCode(code);}else if(getIntent().getBooleanExtra("showShopping",false)){getIntent().removeExtra("showShopping");shopping();}});}
    private void draw(String filter){if(state==null||items==null)return;items.removeAllViews();for(var p:state.activeProducts())if(p.name().toLowerCase(Locale.ROOT).contains(filter.toLowerCase(Locale.ROOT))){long q=state.stock().getOrDefault(p.id(),0L);String alert=q==0?"OUT OF STOCK":q<p.minimum()?"LOW STOCK":"In stock";items.addView(button(p.name()+"\n"+q+" cans · "+alert,()->details(p)));}}
    private void details(Catalog.Product p){shell(p.name());if(state.deleted().contains(p.id())){body.addView(text("Deleted from the working list. Its history and barcode mappings are retained.",18));body.addView(button("Restore flavour",()->job(()->{catalog.restoreProduct(p.id());return true;},ok->showList())));body.addView(button("Back to flavours",this::showList));return;}long q=state.stock().getOrDefault(p.id(),0L);body.addView(text(q+" cans available (pending stock excluded)\nMinimum: "+p.minimum()+" · target: "+p.target()+"\nPreferred supplier: "+(p.supplier().isEmpty()?"not set":p.supplier()),20));if(!p.id().equals(Catalog.LEGACY))body.addView(button("Rename flavour",()->renameFlavour(p)));body.addView(button("Edit thresholds, pack estimate & supplier",()->edit(p)));body.addView(button("Assign a barcode",()->{EditText code=new EditText(this);new AlertDialog.Builder(this).setTitle("Barcode for "+p.name()).setView(code).setNegativeButton("Cancel",null).setPositiveButton("Assign",(d,w)->assign(code.getText().toString(),p)).show();}));body.addView(button("Record a physical stock count",()->count(p)));body.addView(button("Identify / transfer flavour of existing cans",()->transfer(p)));if(!p.id().equals(Catalog.LEGACY))body.addView(button("Delete flavour",()->deleteFlavour(p)));body.addView(button("Back to flavours",this::showList));}
    private void renameFlavour(Catalog.Product p){EditText name=new EditText(this);name.setSingleLine(true);name.setText(p.name());name.setSelectAllOnFocus(true);new AlertDialog.Builder(this).setTitle("Rename flavour").setMessage("Change the displayed name. Stock, barcodes, costs and past transactions stay linked to the same flavour. The old and new names are kept in the audit.").setView(name).setNegativeButton("Cancel",null).setPositiveButton("Rename",(d,w)->job(()->{catalog.rename(p.id(),name.getText().toString());return true;},ok->showList())).show();}
    private void deleteFlavour(Catalog.Product p){new AlertDialog.Builder(this).setTitle("Delete "+p.name()+"?").setMessage("Remove this flavour from sales, purchases, barcode selection and shopping alerts. Past records and reports are kept. You can restore it from Deleted flavours.\n\nIt must have no stock, unreceived goods or pending payment.").setNegativeButton("Keep flavour",null).setPositiveButton("Delete flavour",(d,w)->job(()->{catalog.remove(p.id());return true;},ok->showList())).show();}
    private void deletedFlavours(){shell("Deleted flavours");body.addView(button("Back to flavours",this::showList));job(catalog::view,result->{state=result;if(state.deletedProducts().isEmpty())body.addView(text("No deleted flavours.",18));for(var p:state.deletedProducts())body.addView(button(p.name()+" · restore",()->new AlertDialog.Builder(this).setTitle("Restore "+p.name()+"?").setMessage("Make this flavour available again with its existing settings, barcodes and history.").setNegativeButton("Cancel",null).setPositiveButton("Restore",(d,w)->job(()->{catalog.restoreProduct(p.id());return true;},ok->showList())).show()));});}
    private void edit(Catalog.Product p){LinearLayout fields=new LinearLayout(this);fields.setOrientation(1);EditText name=field(fields,"Flavour name",p==null?"Monster ":p.name(),1);if(p!=null)name.setEnabled(false);EditText min=field(fields,"Minimum cans",p==null?"5":String.valueOf(p.minimum()),2),target=field(fields,"Target cans",p==null?"24":String.valueOf(p.target()),2),pack=field(fields,"Preferred purchase pack size",p==null?"24":String.valueOf(p.packSize()),2),cost=field(fields,"Estimated pack cost AUD (0 = unknown)",p==null?"50.00":Ledger.inputMoney(p.packCost()),8194),supplier=field(fields,"Preferred supplier (optional)",p==null?"":p.supplier(),1);ScrollView scroll=new ScrollView(this);scroll.addView(fields);String id=p==null?Ledger.id():p.id();AlertDialog dialog=new AlertDialog.Builder(this).setTitle(p==null?"Add flavour":"Flavour settings").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{var product=new Catalog.Product(id,name.getText().toString().trim(),Long.parseLong(min.getText().toString()),Long.parseLong(target.getText().toString()),Long.parseLong(pack.getText().toString()),Ledger.cents(cost.getText().toString()),supplier.getText().toString());dialog.dismiss();job(()->{catalog.save(product);return true;},ok->showList());}catch(Exception e){error(e);}}));dialog.show();}
    private void shopping(){shell("Shopping list");body.addView(button("Back to flavours",this::showList));job(catalog::view,result->{state=result;long total=0;for(var s:state.activeShopping())if(s.low()){String estimate=s.product().packCost()==0?"cost estimate not set":Ledger.money(s.estimatedCost());total+=s.estimatedCost();body.addView(text(s.product().name()+"\nOn hand "+s.onHand()+" · ordered/unreceived "+s.ordered()+"\nNeed "+s.required()+" cans → "+s.packs()+" × "+s.product().packSize()+" packs\n"+estimate+" · "+s.product().supplier(),18));}body.addView(text("Known estimated total: "+Ledger.money(total)+"\nUnreceived purchase lines reduce shopping requirements, but never increase actual stock until confirmed. Create/review purchases in Stock > Supplier purchases.",15));status.setText("All shopping calculations are local. Estimates are not financial cost records.");});}
    private void selectCode(String raw){try{String code=Catalog.barcode(raw);job(()->catalog.lookup(code),p->{if(p!=null){stateProduct(p.id(),()->details(p));}else {String[] labels=state.activeProducts().stream().map(Catalog.Product::name).toArray(String[]::new);new AlertDialog.Builder(this).setTitle("Choose flavour for barcode "+code).setItems(labels,(d,index)->assign(code,state.activeProducts().get(index))).setPositiveButton("Create flavour",(d,w)->{pendingBarcode=code;edit(null);}).setNegativeButton("Cancel",null).show();}});}catch(Exception e){error(e);}}
    private void stateProduct(String id,Runnable run){job(catalog::view,result->{state=result;run.run();});}
    private void assign(String raw,Catalog.Product p){try{String code=Catalog.barcode(raw);Catalog.Product old=catalog.lookupIncludingDeleted(code);String message=old!=null&&!old.id().equals(p.id())?"Reassign from "+old.name()+" to "+p.name()+"? The change is retained in the audit.":"Associate "+code+" with "+p.name()+"? This does not add stock.";new AlertDialog.Builder(this).setTitle("Confirm barcode assignment").setMessage(message).setNegativeButton("Cancel",null).setPositiveButton("Confirm",(d,w)->job(()->{catalog.assign(code,p.id(),true);return true;},ok->{status.setText("Barcode saved offline.");setResult(RESULT_OK,new Intent().putExtra("productId",p.id()));if(getIntent().hasExtra("barcode"))finish();else showList();})).show();}catch(Exception e){error(e);}}
    private void count(Catalog.Product p){if(CatalogStore.reserved(store).getOrDefault(p.id(),0L)>0){error(new IllegalArgumentException("Resolve the pending Stripe payment for this flavour before a physical count; its reserved cans must not be counted twice. Other flavours remain usable offline."));return;}EditText q=new EditText(this);q.setInputType(2);q.setText(String.valueOf(state.stock().getOrDefault(p.id(),0L)));String id=Ledger.id();new AlertDialog.Builder(this).setTitle("Actual cans physically counted").setMessage("A shortage creates a missing-stock adjustment. A surplus adds recovered/unpriced stock at zero recorded cost and is clearly labelled; it is not assumed to be a new purchase.").setView(q).setNegativeButton("Cancel",null).setPositiveButton("Confirm count",(d,w)->{try{long actual=Long.parseLong(q.getText().toString());if(actual<0||actual>10000)Purchases.bad("Count must be 0–10,000.");job(()->{var db=store.database();db.beginTransaction();try{if(CatalogStore.reserved(store).getOrDefault(p.id(),0L)>0)Purchases.bad("This flavour now has a pending Stripe reservation. Resolve it before counting.");long current=catalog.view().stock().getOrDefault(p.id(),0L),difference=actual-current;if(difference!=0){var e=new Ledger.Event(id,System.currentTimeMillis(),System.currentTimeMillis(),difference>0?"restock":"missing",Math.abs(difference),"none",0,0,0,difference>0?"Physical count surplus: acquisition cost unknown":"Physical count shortage",null);catalog.stage(e,p.id(),false);store.recoverPending();store.acknowledge(e.id());}db.setTransactionSuccessful();return true;}finally{db.endTransaction();}},ok->showList());}catch(Exception e){error(e);}}).show();}
    private void transfer(Catalog.Product target){List<Catalog.Product> from=new ArrayList<>();for(var p:state.activeProducts())if(!p.id().equals(target.id()))from.add(p);if(from.isEmpty()){error(new IllegalArgumentException("Create another flavour first."));return;}LinearLayout form=new LinearLayout(this);form.setOrientation(1);Spinner spinner=new Spinner(this);spinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,from.stream().map(Catalog.Product::name).toArray(String[]::new)));form.addView(spinner);EditText quantity=field(form,"Existing cans to identify as "+target.name(),"1",2);String id=Ledger.id();long now=System.currentTimeMillis();new AlertDialog.Builder(this).setTitle("Reclassify existing stock").setMessage("Total inventory and historical sales stay unchanged. This flavour transfer is appended to the audit. To reverse a mistake, transfer the cans back explicitly.").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Confirm transfer",(d,w)->{try{var t=new Catalog.Transfer(id,from.get(spinner.getSelectedItemPosition()).id(),target.id(),Long.parseLong(quantity.getText().toString()),now,"Identify existing flavour");job(()->{catalog.transfer(t);return true;},ok->showList());}catch(Exception e){error(e);}}).show();}
    @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==71&&result==RESULT_OK&&data!=null)selectCode(data.getStringExtra("barcode"));}
}

